function race(array $jobs):array{$base=dirname(__DIR__,2).'/.local-setup/cash-discrepancy-race-'.rk();$workers=[];foreach($jobs as $i=>$j){$p=proc_open([PHP_BINARY,__DIR__.'/cash_discrepancy_worker.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);fwrite($pipes[0],json_encode($j+['barrier'=>$base,'worker'=>$i]));fclose($pipes[0]);$workers[]=[$p,$pipes];}$until=microtime(true)+20;while(!is_file($base.'.ready0')||!is_file($base.'.ready1')){if(microtime(true)>$until)throw new RuntimeException('Worker readiness timeout');usleep(10000);}file_put_contents($base.'.go','go');$out=[];foreach($workers as [$p,$pipes]){$text=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);if(proc_close($p)!==0||$err)throw new RuntimeException('Worker failed '.$err);$out[]=json_decode($text,true,512,JSON_THROW_ON_ERROR);}foreach(['.ready0','.ready1','.go'] as $suffix)unlink($base.$suffix);return $out;}
